import{_ as o,o as t,c as n,a2 as a}from"./chunks/framework.uw_ZoRon.js";const l=JSON.parse('{"title":"Components & the actor world","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/components-and-the-actor-world.md","filePath":"deep-dive/components-and-the-actor-world.md"}'),s={name:"deep-dive/components-and-the-actor-world.md"};function r(c,e,i,d,m,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="components-the-actor-world" tabindex="-1">Components &amp; the actor world <a class="header-anchor" href="#components-the-actor-world" aria-label="Permalink to &quot;Components &amp; the actor world&quot;">​</a></h1><p>RUSM hosts WebAssembly the modern way — as <strong>components</strong> — but composes them the Erlang way. A process body can be a <strong>WASI component</strong> (the component-model artifact <code>cargo component</code>, <code>jco</code>, and wasmCloud emit) or an older <strong>wasip1 core module</strong> (the flat artifact Lunatic hosts). Either way it runs instance-per-process as a real <code>rusm-otp</code> process; the two differ only in <em>how</em> they reach the runtime.</p><h2 id="the-rusm-runtime-actor-world" tabindex="-1">The <code>rusm:runtime</code> actor world <a class="header-anchor" href="#the-rusm-runtime-actor-world" aria-label="Permalink to &quot;The `rusm:runtime` actor world&quot;">​</a></h2><p>A component imports the <strong><code>rusm:runtime/actor</code></strong> interface — a real WIT world bound with <code>wasmtime::component::bindgen!</code>. That hands a guest, in <em>any</em> language, the Erlang <code>Process</code> API as typed functions: <code>own-pid</code>, <code>send</code>, <code>receive</code> (async), <code>list-processes</code>, <code>info</code>, <code>is-alive</code>, <code>kill</code>, <code>register</code>/<code>whereis</code>/<code>unregister</code>, <code>set-label</code>. Each is a thin lift → call-<code>rusm-otp</code> → lower, so the runtime stays the single source of truth — never reimplemented in the guest.</p><p>A core module gets the <em>same</em> operations as flat <code>rusm::*</code> imports that marshal through linear memory (pointer + length) — see the <a href="/rusm/deep-dive/host-abi-reference">host ABI</a>.</p><h2 id="composition-is-message-passing-not-wit-wiring" tabindex="-1">Composition is message passing, not WIT wiring <a class="header-anchor" href="#composition-is-message-passing-not-wit-wiring" aria-label="Permalink to &quot;Composition is message passing, not WIT wiring&quot;">​</a></h2><p>This is the design choice that sets RUSM apart. Components do <strong>not</strong> link to each other through WIT imports, and there is no lattice. They compose the Erlang way: spawn instances, then <code>register</code>/<code>whereis</code> to find each other and <code>send</code>/<code>receive</code> to talk. A request/reply &quot;callback&quot; between two components is just a message and a reply — no new runtime API, no static dependency graph to maintain.</p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h2><p>You get the whole component ecosystem — capabilities, language portability, WASI p1/p2/p3 — running <em>on</em> the BEAM&#39;s process model: long-lived, addressable, supervised, preemptible, killable, with <strong>no execution-time cap</strong>. The <strong>component-storm</strong> benchmark hosts ~440k component instances/sec.</p><blockquote><p>Shipped in Phase 7.</p></blockquote>',10)])])}const u=o(s,[["render",r]]);export{l as __pageData,u as default};
